<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';
function api_vendor(): array{$h=$_SERVER['HTTP_AUTHORIZATION']??'';if(!preg_match('/^Bearer\s+(.+)$/i',$h,$m))json_response(false,'Unauthorized request',null,401);$s=db()->prepare("SELECT vu.*,v.name vendor_name,v.shop_name,v.vendor_code FROM vendor_sessions vs JOIN vendor_users vu ON vu.id=vs.vendor_user_id JOIN vendors v ON v.id=vu.vendor_id WHERE vs.token_hash=? AND vs.revoked_at IS NULL AND vs.expires_at>NOW() AND vu.status='ACTIVE' AND v.status='ACTIVE'");$s->execute([hash('sha256',$m[1])]);$u=$s->fetch();if(!$u)json_response(false,'Unauthorized request',null,401);return $u;}
